&lt;tr&gt;
&lt;td&gt;swarm_tc_upload&lt;/td&gt;&lt;td&gt;&amp;lt;src_bucket_hw_id&amp;gt; &amp;lt;src_bucketsw_id&amp;gt; &amp;lt;dst_bucket_hw_id&amp;gt; &amp;lt;dst_bucket_sw_id&amp;gt; &amp;lt;work_dir&amp;gt; &amp;lt;appid&amp;gt; &amp;lt;bucketid&amp;gt;&lt;/td&gt;&lt;/tr&gt;
